import heapq

def max_path_sum(root: list) -> int:
    best = [float("-inf")]

    def gain(node) -> int:
        if node is None:
            return 0
        left = max(0, gain(node.left))
        right = max(0, gain(node.right))
        best[0] = max(best[0], node.value + left + right)
        return node.value + max(left, right)

    gain(_build(root))
    return int(best[0])

